def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c] and (r,c) not in seen:
    stack=[(r,c)];seen.add((r,c)); pts=[]
    while stack:
     y,x=stack.pop();pts.append((y,x))
     for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
      if 0<=yy<h and 0<=xx<w and g[yy][xx] and (yy,xx) not in seen:
       seen.add((yy,xx));stack.append((yy,xx))
    out.append(pts)
 return out
